            aWandererE = aWandererE ^ ((RotL64(aCross, 3U) + aOrbiterJ) + RotL64(aOrbiterH, 3U));
            aWandererG = aWandererG + (((RotL64(aIngress, 53U) + RotL64(aOrbiterG, 11U)) + aOrbiterB) + aNonceWordK);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 40U) + RotL64(aOrbiterE, 47U)) + aOrbiterD);
            aWandererF = aWandererF + (((RotL64(aPrevious, 51U) + aOrbiterI) + RotL64(aOrbiterC, 19U)) + RotL64(aCarry, 37U));
            aWandererA = aWandererA ^ (((RotL64(aCross, 35U) + RotL64(aOrbiterA, 29U)) + aOrbiterJ) + aWUSaltH[((aIndex + 335U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aIngress, 23U) + RotL64(aOrbiterK, 54U)) + aOrbiterG) + aWUSaltD[(((511U - aIndex) + 24U)) & S_SALT1]);
