            aIngress ^= (RotL64(aCrystalLaneD[((aIndex + 7767U)) & S_BLOCK1], 48U) ^ RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 8829U)) & S_BLOCK1], 57U));
