            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x1F67C86E56A51DBFULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0xB3960BE9D7ED7933ULL) ^ aOUSaltC[((aIndex + 126U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x9FCB0D789E21585FULL), 21U);
