            aWandererK = aWandererK ^ ((RotL64(aIngress, 19U) + RotL64(aOrbiterA, 43U)) + aOrbiterB);
            aWandererA = aWandererA + ((RotL64(aScatter, 57U) + aOrbiterK) + RotL64(aOrbiterA, 19U));
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterI, 48U)) + aOrbiterG);
