            aWandererC = aWandererC ^ ((RotL64(aIngress, 14U) + RotL64(aOrbiterD, 23U)) + aOrbiterI);
            //
            aCarry = aCarry + (RotL64(aWandererG, 30U) ^ aWandererC);
