            aWandererD = aWandererD + (((RotL64(aScatter, 11U) + RotL64(aOrbiterI, 29U)) + aOrbiterD) + RotL64(aCarry, 57U));
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 57U) + aOrbiterD) + RotL64(aOrbiterG, 21U));
            aWandererA = aWandererA + ((RotL64(aCross, 13U) + aOrbiterJ) + RotL64(aOrbiterE, 51U));
            aWandererH = aWandererH ^ ((RotL64(aIngress, 48U) + aOrbiterB) + RotL64(aOrbiterJ, 23U));
            aWandererJ = aWandererJ + (((RotL64(aScatter, 37U) + aOrbiterG) + RotL64(aOrbiterH, 10U)) + aWUSaltH[((aIndex + 428U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererB, 56U));
