            aIngress ^= (RotL64(aPlasmaLaneA[((aIndex + 11619U)) & S_BLOCK1], 47U) ^ RotL64(aIceLaneC[((S_BLOCK1 - aIndex + 9612U)) & S_BLOCK1], 37U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateBDomainWordIngress));
